# check mismatch for any pairs across vertical/horizontal when neither is overlay
mis=[]
for r in range(24):
 for c in range(24):
  for rr,cc in [(r,23-c),(23-r,c)]:
   if a[r][c]!=2 and a[rr][cc]!=2 and a[r][c]!=a[rr][cc]: mis.append(((r,c),a[r][c],(rr,cc),a[rr][cc]))
len(mis),mis[:10]

b=[row[:] for row in a]
conf=[]; unresolved=[]
for r in range(24):
 for c in range(24):
  if a[r][c]==2:
   vals=[a[rr][cc] for rr,cc in [(r,23-c),(23-r,c),(23-r,23-c)] if a[rr][cc]!=2]
   if not vals: unresolved.append((r,c))
   else:
    if len(set(vals))>1: conf.append(((r,c),vals))
    b[r][c]=vals[0]
len(unresolved),conf, '\n'.join(' '.join(map(str,row)) for row in b)

