for r in range(24):
 for c in range(24):
  if a[r][c]!=2 and a[c][r]!=2 and a[r][c]!=a[c][r]: misdiag.append((r,c,a[r][c],a[c][r]))
len(misdiag),misdiag[:20]

for r in range(24):
 for c in range(24):
  if a[r][c]==2 and b[r][c]==2:
   b[r][c]=a[c][r]
[(r,c,a[c][r]) for r in range(24) for c in range(24) if a[r][c]==2 and a[c][r]==2], '\n'.join(' '.join(map(str,row)) for row in b)
